# -*- coding: utf-8 -*-
"""
fix_mega_ai_assistant.py

Максимально улучшает ИИ-ассистента:
1) полностью заменяет src/ai_assistant.py на сильную rule-based экспертную систему;
2) улучшает вкладку ИИ в main.py;
3) добавляет защиту от вопросов не по теме недвижимости;
4) добавляет анализ цены, района, микрорайона, инфраструктуры, рисков, торга и инвестиций.

Запускать из папки проекта:
python fix_mega_ai_assistant.py
"""

from pathlib import Path
import re
import shutil
import py_compile

MAIN_PATH = Path("main.py")
AI_PATH = Path("src/ai_assistant.py")

if not MAIN_PATH.exists():
    raise FileNotFoundError("main.py не найден. Запусти файл из папки проекта.")
if not AI_PATH.exists():
    raise FileNotFoundError("src/ai_assistant.py не найден.")

for p in [MAIN_PATH, AI_PATH]:
    b = p.with_suffix(p.suffix + ".backup_mega_ai")
    if not b.exists():
        shutil.copyfile(p, b)
        print("Backup:", b)

NEW_AI_ASSISTANT = "# -*- coding: utf-8 -*-\n\"\"\"\nУлучшенный ИИ-ассистент для анализа недвижимости Алматы.\n\nРаботает без API-ключа: rule-based экспертная система.\nЕсли задан ANTHROPIC_API_KEY, пробует Claude API, но всё равно ограничивает тему недвижимостью.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport os\nimport re\nimport math\nimport json\nfrom typing import Any, Dict, List, Tuple\n\ntry:\n    import requests\nexcept Exception:\n    requests = None\n\ntry:\n    from dotenv import load_dotenv\n    load_dotenv()\nexcept Exception:\n    pass\n\n\n# ============================================================\n# Тема ассистента: только недвижимость Алматы\n# ============================================================\n\nREAL_ESTATE_KEYWORDS = {\n    \"цена\", \"стоимость\", \"дорого\", \"дешево\", \"дёшево\", \"почему\", \"район\", \"микрорайон\",\n    \"адрес\", \"локация\", \"координат\", \"карта\", \"квартира\", \"дом\", \"жк\", \"жилой\",\n    \"недвиж\", \"объект\", \"метр\", \"м2\", \"м²\", \"квадрат\", \"площадь\", \"комнат\",\n    \"этаж\", \"год\", \"построй\", \"ремонт\", \"мебель\", \"ипотека\", \"инфраструктура\",\n    \"рядом\", \"школ\", \"сад\", \"больниц\", \"клиник\", \"аптек\", \"магазин\", \"трц\",\n    \"парк\", \"метро\", \"останов\", \"университет\", \"театр\", \"музей\", \"сравни\",\n    \"сравнение\", \"средняя\", \"переплата\", \"скидка\", \"торг\", \"инвест\", \"сдать\",\n    \"аренда\", \"жить\", \"для жизни\", \"подходит\", \"риск\", \"минус\", \"плюс\",\n    \"алматы\", \"медеу\", \"бостандык\", \"алмалы\", \"алмалин\", \"ауэзов\", \"жетысу\",\n    \"турксиб\", \"алатау\", \"наурызбай\"\n}\n\nOFFTOPIC_PATTERNS = [\n    r\"^\\s*\\d+\\s*[\\+\\-\\*/]\\s*\\d+\\s*$\",\n    r\"сколько будет\\s+\\d+\",\n    r\"реши\\s+пример\",\n    r\"напиши\\s+код\",\n    r\"политик\",\n    r\"футбол\",\n    r\"погода\",\n    r\"курс валют\",\n    r\"переведи\",\n    r\"кто такой\",\n]\n\n\n# ============================================================\n# Контекст районов Алматы\n# ============================================================\n\nDISTRICT_CONTEXT = {\n    \"Медеуский\": {\n        \"class\": \"премиальный / престижный\",\n        \"factors\": [\n            \"близость к горам, Медеу, Шымбулаку и зелёным зонам\",\n            \"имидж престижной локации\",\n            \"много бизнес- и культурных объектов\",\n            \"часто выше спрос на жильё бизнес- и премиум-класса\",\n        ],\n        \"risks\": [\n            \"высокая база цены — сложнее найти недооценённый объект\",\n            \"часть объектов может быть старого фонда\",\n            \"парковка и пробки в популярных местах\",\n        ],\n    },\n    \"Бостандыкский\": {\n        \"class\": \"престижный / деловой / семейный\",\n        \"factors\": [\n            \"проспект Аль-Фараби, бизнес-центры, университеты, ТРЦ\",\n            \"хорошая транспортная доступность\",\n            \"много современных ЖК\",\n            \"высокий спрос со стороны семей, студентов и специалистов\",\n        ],\n        \"risks\": [\n            \"цены в популярных зонах могут быть сильно выше среднего\",\n            \"пробки на ключевых магистралях\",\n            \"качество ЖК сильно различается\",\n        ],\n    },\n    \"Алмалинский\": {\n        \"class\": \"исторический центр\",\n        \"factors\": [\n            \"Золотой квадрат, Арбат, ЦУМ, театры, музеи, историческая застройка\",\n            \"очень насыщенная инфраструктура\",\n            \"центральное расположение и высокая ликвидность\",\n            \"удобство для аренды и городской жизни\",\n        ],\n        \"risks\": [\n            \"часто старый фонд и износ коммуникаций\",\n            \"парковка, шум и плотная застройка\",\n            \"нужно внимательно смотреть год дома и состояние подъезда\",\n        ],\n    },\n    \"Ауэзовский\": {\n        \"class\": \"массовый жилой / семейный\",\n        \"factors\": [\n            \"много крупных микрорайонов и советских кварталов\",\n            \"развитая бытовая инфраструктура\",\n            \"обычно цены умереннее центра\",\n            \"хороший спрос на доступное жильё\",\n        ],\n        \"risks\": [\n            \"в разных микрорайонах качество среды сильно отличается\",\n            \"у старого фонда важны состояние дома и коммуникаций\",\n            \"транспортная доступность зависит от конкретной улицы\",\n        ],\n    },\n    \"Жетысуский\": {\n        \"class\": \"умеренный / жилой\",\n        \"factors\": [\n            \"много жилых зон и базовой инфраструктуры\",\n            \"обычно цены ниже премиальных районов\",\n            \"подходит для покупателей с ограниченным бюджетом\",\n        ],\n        \"risks\": [\n            \"не везде одинаковая транспортная доступность\",\n            \"промышленные зоны рядом могут снижать привлекательность\",\n            \"важно смотреть конкретное окружение дома\",\n        ],\n    },\n    \"Турксибский\": {\n        \"class\": \"доступный / промышленно-жилой\",\n        \"factors\": [\n            \"обычно более доступные цены\",\n            \"близость к вокзалу, аэропорту и промышленным зонам\",\n            \"может быть интересен при ограниченном бюджете\",\n        ],\n        \"risks\": [\n            \"часть локаций менее престижная\",\n            \"шум, транспорт и промзоны могут снижать цену\",\n            \"ликвидность зависит от конкретного места\",\n        ],\n    },\n    \"Алатауский\": {\n        \"class\": \"новая застройка / развивающийся\",\n        \"factors\": [\n            \"много новых ЖК и активно развивающихся массивов\",\n            \"цены часто доступнее центра\",\n            \"потенциал роста при развитии инфраструктуры\",\n        ],\n        \"risks\": [\n            \"инфраструктура может отставать от темпов застройки\",\n            \"нужно проверять дороги, школы, поликлиники и транспорт\",\n            \"ликвидность зависит от качества ЖК\",\n        ],\n    },\n    \"Наурызбайский\": {\n        \"class\": \"развивающийся / предгорный\",\n        \"factors\": [\n            \"предгорная локация, новые жилые массивы\",\n            \"может быть привлекательным для семей\",\n            \"потенциал роста при развитии дорог и инфраструктуры\",\n        ],\n        \"risks\": [\n            \"инфраструктура не везде зрелая\",\n            \"важна доступность дорог и общественного транспорта\",\n            \"качество новых ЖК нужно проверять отдельно\",\n        ],\n    },\n}\n\n\nMICRO_CONTEXT_HINTS = {\n    \"Самал\": \"Самал — престижная центральная зона рядом с Достык/Аль-Фараби, бизнесом, ТРЦ и культурной инфраструктурой.\",\n    \"Коктем\": \"Коктем ценится за близость к центру, университетам и деловым зонам, при этом часто спокойнее самого центра.\",\n    \"Орбита\": \"Орбита — востребованные жилые микрорайоны Бостандыкского/Ауэзовского направления с хорошей бытовой инфраструктурой.\",\n    \"Мамыр\": \"Мамыр — массовые жилые микрорайоны с развитой повседневной инфраструктурой и более умеренными ценами.\",\n    \"Аксай\": \"Аксай — крупная жилая зона с доступным сегментом, спросом на семейное жильё и развитой торговой инфраструктурой.\",\n    \"Жетысу\": \"Жетысу — жилые микрорайоны Ауэзовского направления; цены часто зависят от близости к магистралям, школам и состоянию дома.\",\n    \"Айнабулак\": \"Айнабулак — массовая жилая зона с более доступным уровнем цен относительно центра.\",\n    \"Калкаман\": \"Калкаман — развивающаяся западная зона; важны дороги, транспорт и качество нового строительства.\",\n    \"Таугуль\": \"Таугуль — жилой массив с умеренными ценами; ценность зависит от инфраструктуры и транспортной доступности.\",\n    \"Казахфильм\": \"Казахфильм обычно воспринимается как более престижная зелёная зона, особенно при хорошей близости к Аль-Фараби.\",\n    \"Алмагуль\": \"Алмагуль ценится за близость к Бостандыкским деловым и образовательным локациям.\",\n    \"Золотой квадрат\": \"Золотой квадрат — исторически дорогая центральная зона с высокой ликвидностью, культурой, бизнесом и плотной инфраструктурой.\",\n    \"Арбат\": \"Арбат — центральная городская зона с культурой, торговлей и высокой пешеходной активностью.\",\n}\n\n\nGOOD_INFRA = {\n    \"Школы\", \"Университеты\", \"Детские сады\", \"Больницы\", \"Клиники\", \"Аптеки\",\n    \"Парки\", \"Торговые центры\", \"Магазины\", \"Рестораны\", \"Кафе\",\n    \"Театры\", \"Музеи\", \"Остановки\", \"Метро\", \"Банки\", \"Спорт\"\n}\n\nVERY_IMPORTANT_INFRA = {\n    \"Школы\", \"Детские сады\", \"Больницы\", \"Клиники\", \"Парки\",\n    \"Торговые центры\", \"Метро\", \"Остановки\", \"Университеты\"\n}\n\n\n# ============================================================\n# Utility\n# ============================================================\n\ndef _fmt_num(value: Any, suffix: str = \"\") -> str:\n    try:\n        if value is None:\n            return \"нет данных\"\n        if isinstance(value, str):\n            if value.strip() in [\"\", \"—\", \"None\", \"nan\", \"Не определён\"]:\n                return \"нет данных\"\n            value = float(value.replace(\" \", \"\").replace(\",\", \".\"))\n        if math.isnan(float(value)):\n            return \"нет данных\"\n        return f\"{int(round(float(value))):,}{suffix}\".replace(\",\", \" \")\n    except Exception:\n        return str(value) if value not in [None, \"\"] else \"нет данных\"\n\n\ndef _safe_float(value: Any) -> float | None:\n    try:\n        if value in [None, \"\", \"—\"]:\n            return None\n        if isinstance(value, str):\n            value = value.replace(\"₸\", \"\").replace(\"м²\", \"\").replace(\"м2\", \"\")\n            value = value.replace(\" \", \"\").replace(\",\", \".\")\n        x = float(value)\n        if math.isnan(x):\n            return None\n        return x\n    except Exception:\n        return None\n\n\ndef _clean_text(value: Any, default: str = \"—\") -> str:\n    if value is None:\n        return default\n    s = str(value).strip()\n    if not s or s.lower() in [\"nan\", \"none\", \"не определён\", \"не определен\"]:\n        return default\n    return s\n\n\ndef _is_relevant_question(question: str) -> bool:\n    q = (question or \"\").lower().strip()\n\n    if not q:\n        return False\n\n    for pat in OFFTOPIC_PATTERNS:\n        if re.search(pat, q):\n            # Если есть одновременно недвижимость — всё же разрешаем\n            if any(k in q for k in REAL_ESTATE_KEYWORDS):\n                return True\n            return False\n\n    return any(k in q for k in REAL_ESTATE_KEYWORDS)\n\n\ndef _topic_refusal() -> str:\n    return (\n        \"⚠️ **Я отвечаю только по выбранной недвижимости Алматы.**\\n\\n\"\n        \"Могу помочь с вопросами про цену, район, микрорайон, инфраструктуру рядом, \"\n        \"сравнение со средней ценой, ликвидность, риски, плюсы/минусы, торг и пригодность для жизни.\\n\\n\"\n        \"Примеры вопросов:\\n\"\n        \"- Почему здесь такая цена?\\n\"\n        \"- Дорого ли это для района?\\n\"\n        \"- Что рядом влияет на цену?\\n\"\n        \"- Какие риски у этой квартиры?\\n\"\n        \"- Стоит ли торговаться?\"\n    )\n\n\ndef _property_summary(prop: dict) -> dict:\n    ppm2 = _safe_float(prop.get(\"price_per_m2_raw\") or prop.get(\"price_per_m2\"))\n    price = prop.get(\"price\", \"—\")\n    district = _clean_text(prop.get(\"district\"), \"район не определён\")\n    micro = _clean_text(prop.get(\"microdistrict\"), \"микрорайон не определён\")\n    address = _clean_text(prop.get(\"address\"), \"адрес не определён\")\n    year = _safe_float(prop.get(\"year\"))\n    rooms = _clean_text(prop.get(\"rooms\"), _clean_text(prop.get(\"live_rooms\"), \"—\"))\n    square = _clean_text(prop.get(\"square\"), _clean_text(prop.get(\"live_square\"), \"—\"))\n    floor = _clean_text(prop.get(\"floor\"), \"—\")\n    building = _clean_text(prop.get(\"building\"), \"—\")\n    renovation = _clean_text(prop.get(\"renovation\"), \"—\")\n    complex_name = _clean_text(prop.get(\"complex\"), _clean_text(prop.get(\"complex_name\"), \"—\"))\n    mortgage = _clean_text(prop.get(\"mortgage\"), \"—\")\n    furniture = _clean_text(prop.get(\"furniture\"), \"—\")\n\n    return {\n        \"ppm2\": ppm2,\n        \"price\": price,\n        \"district\": district,\n        \"micro\": micro,\n        \"address\": address,\n        \"year\": int(year) if year else None,\n        \"rooms\": rooms,\n        \"square\": square,\n        \"floor\": floor,\n        \"building\": building,\n        \"renovation\": renovation,\n        \"complex\": complex_name,\n        \"mortgage\": mortgage,\n        \"furniture\": furniture,\n    }\n\n\ndef _district_avg(district_stats: dict, district: str) -> float | None:\n    if not district_stats:\n        return None\n\n    direct = district_stats.get(district)\n    if isinstance(direct, dict):\n        return _safe_float(direct.get(\"avg\") or direct.get(\"mean\") or direct.get(\"median\"))\n\n    # fallback: clean names\n    clean = district.replace(\" (приближённо)\", \"\").strip()\n    for k, v in district_stats.items():\n        if str(k).replace(\" (приближённо)\", \"\").strip() == clean and isinstance(v, dict):\n            return _safe_float(v.get(\"avg\") or v.get(\"mean\") or v.get(\"median\"))\n    return None\n\n\ndef _comparison(ppm2: float | None, avg: float | None, label: str = \"района\") -> tuple[str, float | None]:\n    if ppm2 is None or avg is None or avg <= 0:\n        return \"Нет достаточно данных для точного сравнения со средней ценой.\", None\n\n    diff_pct = (ppm2 - avg) / avg * 100\n    if abs(diff_pct) < 3:\n        return f\"Цена за м² почти соответствует средней по {label}: разница около {diff_pct:+.1f}%.\", diff_pct\n    if diff_pct > 0:\n        return f\"Цена за м² выше средней по {label} на {diff_pct:.1f}%.\", diff_pct\n    return f\"Цена за м² ниже средней по {label} на {abs(diff_pct):.1f}%.\", diff_pct\n\n\ndef _price_category(ppm2: float | None) -> tuple[str, str]:\n    if ppm2 is None:\n        return \"⚫\", \"нет данных по цене за м²\"\n    if ppm2 >= 1_000_000:\n        return \"🔴\", \"очень дорогой сегмент Алматы\"\n    if ppm2 >= 700_000:\n        return \"🟠\", \"дорогой сегмент\"\n    if ppm2 >= 500_000:\n        return \"🟡\", \"средне-высокий сегмент\"\n    if ppm2 >= 300_000:\n        return \"🟢\", \"средний / относительно доступный сегмент\"\n    return \"🔵\", \"низкий сегмент относительно шкалы проекта\"\n\n\ndef _micro_hint(micro: str) -> str:\n    for key, hint in MICRO_CONTEXT_HINTS.items():\n        if key.lower() in micro.lower():\n            return hint\n    return \"\"\n\n\ndef _district_context(district: str) -> dict:\n    clean = district.replace(\" (приближённо)\", \"\").strip()\n    return DISTRICT_CONTEXT.get(clean, {})\n\n\ndef _iter_nearby(nearby_places: dict) -> list[dict]:\n    rows = []\n    if not nearby_places or not isinstance(nearby_places, dict):\n        return rows\n\n    for cat, items in nearby_places.items():\n        if str(cat).startswith(\"_\") or not isinstance(items, list):\n            continue\n\n        for item in items:\n            if not isinstance(item, dict):\n                continue\n            name = _clean_text(item.get(\"name\"), \"Без названия\")\n            dist = _safe_float(item.get(\"distance\"))\n            typ = _clean_text(item.get(\"type\"), \"\")\n            address = _clean_text(item.get(\"address\"), \"\")\n            rows.append({\n                \"category\": str(cat),\n                \"name\": name,\n                \"distance\": int(dist) if dist is not None else 999999,\n                \"type\": typ,\n                \"address\": address,\n            })\n\n    rows.sort(key=lambda x: x[\"distance\"])\n    return rows\n\n\ndef _infra_summary(nearby_places: dict) -> dict:\n    rows = _iter_nearby(nearby_places)\n    by_cat = {}\n    for r in rows:\n        by_cat.setdefault(r[\"category\"], []).append(r)\n\n    strongest = []\n    for cat, items in by_cat.items():\n        if not items:\n            continue\n        nearest = items[0]\n        if cat in VERY_IMPORTANT_INFRA:\n            weight = 3\n        elif cat in GOOD_INFRA:\n            weight = 2\n        else:\n            weight = 1\n\n        strongest.append({\n            \"category\": cat,\n            \"count\": len(items),\n            \"nearest\": nearest,\n            \"weight\": weight,\n        })\n\n    strongest.sort(key=lambda x: (-x[\"weight\"], x[\"nearest\"][\"distance\"]))\n    return {\n        \"rows\": rows,\n        \"by_cat\": by_cat,\n        \"strongest\": strongest,\n        \"total\": len(rows),\n    }\n\n\ndef _quality_score(s: dict, diff_pct: float | None, infra: dict) -> tuple[int, list[str]]:\n    score = 50\n    reasons = []\n\n    ppm2 = s[\"ppm2\"]\n    year = s[\"year\"]\n\n    if diff_pct is not None:\n        if diff_pct <= -10:\n            score += 12\n            reasons.append(\"цена ниже средней по району\")\n        elif diff_pct <= 5:\n            score += 6\n            reasons.append(\"цена близка к среднему уровню\")\n        elif diff_pct >= 25:\n            score -= 14\n            reasons.append(\"сильная переплата относительно района\")\n        elif diff_pct >= 10:\n            score -= 7\n            reasons.append(\"цена выше средней по району\")\n\n    if year:\n        if year >= 2015:\n            score += 10\n            reasons.append(\"новый или относительно новый дом\")\n        elif year < 1985:\n            score -= 8\n            reasons.append(\"старый фонд — нужно проверить состояние дома\")\n        elif year < 2000:\n            score -= 3\n            reasons.append(\"дом не новый, важна проверка коммуникаций\")\n\n    if infra[\"total\"] >= 30:\n        score += 10\n        reasons.append(\"очень насыщенная инфраструктура рядом\")\n    elif infra[\"total\"] >= 12:\n        score += 6\n        reasons.append(\"хорошая инфраструктура рядом\")\n    elif infra[\"total\"] <= 3:\n        score -= 5\n        reasons.append(\"мало найденной инфраструктуры рядом\")\n\n    if ppm2:\n        if ppm2 >= 1_000_000:\n            score -= 4\n            reasons.append(\"высокая цена требует сильного обоснования\")\n        elif ppm2 < 300_000:\n            score += 4\n            reasons.append(\"низкая цена может быть плюсом, но нужно проверить причины\")\n\n    score = max(0, min(100, score))\n    return score, reasons\n\n\ndef _render_header(s: dict, district_avg: float | None, comparison_text: str, diff_pct: float | None, infra: dict) -> str:\n    icon, category = _price_category(s[\"ppm2\"])\n    score, reasons = _quality_score(s, diff_pct, infra)\n\n    lines = [\n        \"## 🏠 Краткий вывод по выбранному объекту\",\n        f\"- **Цена:** {s['price']}\",\n        f\"- **Цена за м²:** {_fmt_num(s['ppm2'], ' ₸/м²')} — {icon} {category}\",\n        f\"- **Локация:** {s['district']} / {s['micro']}\",\n        f\"- **Адрес:** {s['address']}\",\n        f\"- **Оценка привлекательности:** **{score}/100**\",\n    ]\n\n    if comparison_text:\n        lines.append(f\"- **Сравнение:** {comparison_text}\")\n\n    if reasons:\n        lines.append(\"- **Почему такая оценка:** \" + \"; \".join(reasons[:4]) + \".\")\n\n    return \"\\n\".join(lines)\n\n\ndef _render_infra(infra: dict, limit: int = 8) -> str:\n    if not infra[\"rows\"]:\n        return (\n            \"## 📍 Инфраструктура рядом\\n\"\n            \"По текущим данным рядом не найдено достаточно объектов инфраструктуры. \"\n            \"Это может означать как реальную слабую инфраструктуру, так и неполноту данных OpenStreetMap.\"\n        )\n\n    lines = [\"## 📍 Что рядом влияет на цену\"]\n    for item in infra[\"strongest\"][:limit]:\n        n = item[\"nearest\"]\n        lines.append(\n            f\"- **{item['category']}**: {item['count']} объект(ов), ближайший — \"\n            f\"{n['name']} ({n['distance']} м).\"\n        )\n\n    # Ближайшие вообще\n    near = infra[\"rows\"][:5]\n    if near:\n        lines.append(\"\\n**Ближайшие точки:**\")\n        for r in near:\n            lines.append(f\"- {r['category']}: {r['name']} — {r['distance']} м\")\n\n    return \"\\n\".join(lines)\n\n\ndef _render_location_factors(s: dict) -> str:\n    ctx = _district_context(s[\"district\"])\n    micro_hint = _micro_hint(s[\"micro\"])\n\n    lines = [\"## 🏙️ Локационные факторы\"]\n\n    if ctx:\n        lines.append(f\"- **Тип района:** {ctx.get('class', '—')}.\")\n        factors = ctx.get(\"factors\", [])\n        if factors:\n            lines.append(\"- **Факторы роста цены:** \" + \"; \".join(factors[:4]) + \".\")\n        risks = ctx.get(\"risks\", [])\n        if risks:\n            lines.append(\"- **Риски района:** \" + \"; \".join(risks[:3]) + \".\")\n\n    if micro_hint:\n        lines.append(f\"- **Микрорайон:** {micro_hint}\")\n\n    if not ctx and not micro_hint:\n        lines.append(\"По району/микрорайону в базе мало контекста, поэтому важнее смотреть цену за м², дом и инфраструктуру рядом.\")\n\n    return \"\\n\".join(lines)\n\n\ndef _render_building_factors(s: dict) -> str:\n    lines = [\"## 🧱 Факторы самого объекта\"]\n\n    lines.append(f\"- **Комнатность и площадь:** {s['rooms']} комн., {s['square']} м².\")\n    lines.append(f\"- **Этаж:** {s['floor']}.\")\n    lines.append(f\"- **Год постройки:** {s['year'] if s['year'] else 'нет данных'}.\")\n\n    if s[\"building\"] != \"—\":\n        lines.append(f\"- **Тип здания:** {s['building']}.\")\n    if s[\"renovation\"] != \"—\":\n        lines.append(f\"- **Ремонт:** {s['renovation']}.\")\n    if s[\"furniture\"] != \"—\":\n        lines.append(f\"- **Мебель:** {s['furniture']}.\")\n    if s[\"complex\"] != \"—\":\n        lines.append(f\"- **ЖК:** {s['complex']}.\")\n    if s[\"mortgage\"] != \"—\":\n        lines.append(f\"- **Ипотека:** {s['mortgage']}.\")\n\n    year = s[\"year\"]\n    if year:\n        if year >= 2015:\n            lines.append(\"- Новый дом обычно поддерживает цену: покупатели часто платят за современные планировки, лифты, паркинг и инженерные системы.\")\n        elif year < 1985:\n            lines.append(\"- Старый фонд может быть дешевле, но требует проверки коммуникаций, сейсмостойкости, подъезда, лифта и документов.\")\n        else:\n            lines.append(\"- Для дома этого периода важно смотреть состояние подъезда, коммуникаций, фасада и качество ремонта.\")\n\n    return \"\\n\".join(lines)\n\n\ndef _answer_price(s: dict, district_avg: float | None, comparison_text: str, diff_pct: float | None, infra: dict) -> str:\n    lines = [\n        _render_header(s, district_avg, comparison_text, diff_pct, infra),\n        \"\",\n        \"## 💰 Почему цена может быть такой\",\n    ]\n\n    icon, category = _price_category(s[\"ppm2\"])\n    lines.append(f\"- По шкале проекта объект относится к категории: **{icon} {category}**.\")\n\n    if district_avg:\n        lines.append(f\"- Средняя цена по району: **{_fmt_num(district_avg, ' ₸/м²')}**.\")\n        lines.append(f\"- {comparison_text}\")\n\n    lines.append(_render_location_factors(s))\n    lines.append(_render_building_factors(s))\n    lines.append(_render_infra(infra, limit=6))\n\n    lines.append(\n        \"\\n## ✅ Итог\\n\"\n        \"Цена выглядит обоснованной, если совпадают три условия: хорошая локация, нормальное состояние дома \"\n        \"и сильная инфраструктура рядом. Если цена выше средней, проси аргументы: новый дом, ремонт, вид, паркинг, ЖК, \"\n        \"безопасность, документы и ликвидность.\"\n    )\n    return \"\\n\\n\".join(lines)\n\n\ndef _answer_compare(s: dict, district_avg: float | None, comparison_text: str, diff_pct: float | None, infra: dict) -> str:\n    lines = [\n        \"## 📊 Сравнение со средней ценой\",\n        f\"- Объект: **{_fmt_num(s['ppm2'], ' ₸/м²')}**.\",\n    ]\n\n    if district_avg:\n        lines.append(f\"- Средняя по району {s['district']}: **{_fmt_num(district_avg, ' ₸/м²')}**.\")\n        lines.append(f\"- Вывод: **{comparison_text}**.\")\n    else:\n        lines.append(\"- Средняя по району недоступна, поэтому сравнение ограничено.\")\n\n    if diff_pct is not None:\n        if diff_pct >= 20:\n            lines.append(\"\\n**Вероятная переплата.** Покупка может быть оправдана только при сильных плюсах: новый ЖК, отличный ремонт, вид, паркинг, престижная улица.\")\n        elif diff_pct <= -10:\n            lines.append(\"\\n**Цена ниже средней.** Это может быть выгодно, но проверь причины: этаж, состояние, документы, срочность продажи, шум, старый дом.\")\n        else:\n            lines.append(\"\\n**Цена близка к рынку.** Решение зависит от качества дома, ремонта и инфраструктуры.\")\n\n    lines.append(_render_infra(infra, limit=5))\n    return \"\\n\\n\".join(lines)\n\n\ndef _answer_nearby(s: dict, infra: dict) -> str:\n    lines = [_render_infra(infra, limit=12)]\n\n    lines.append(\n        \"\\n## Как это влияет на цену\\n\"\n        \"- **Школы, сады, клиники и остановки** повышают удобство для жизни.\\n\"\n        \"- **Парки, ТРЦ, кафе, театры, музеи** повышают комфорт и престиж.\\n\"\n        \"- Если инфраструктуры много в радиусе 300–800 м, объект обычно ликвиднее для покупки и аренды.\\n\"\n        \"- Но слишком близкие магистрали, шумные кафе или плотная торговля могут быть минусом.\"\n    )\n    return \"\\n\".join(lines)\n\n\ndef _answer_suitability(s: dict, district_avg: float | None, comparison_text: str, diff_pct: float | None, infra: dict) -> str:\n    score, reasons = _quality_score(s, diff_pct, infra)\n\n    lines = [\n        \"## 🧭 Подходит ли объект для жизни?\",\n        f\"Моя оценка пригодности: **{score}/100**.\",\n    ]\n\n    if score >= 75:\n        lines.append(\"**В целом объект выглядит сильным для жизни**, если документы и состояние дома в порядке.\")\n    elif score >= 55:\n        lines.append(\"**Объект средний/нормальный**, решение зависит от деталей: дом, подъезд, шум, парковка, документы.\")\n    else:\n        lines.append(\"**Есть заметные риски**, нужно внимательно проверять объект и торговаться.\")\n\n    if reasons:\n        lines.append(\"\\n**Главные причины оценки:**\")\n        for r in reasons[:6]:\n            lines.append(f\"- {r}\")\n\n    lines.append(_render_building_factors(s))\n    lines.append(_render_infra(infra, limit=6))\n\n    lines.append(\n        \"\\n## Что проверить перед покупкой\\n\"\n        \"- документы и отсутствие обременений;\\n\"\n        \"- фактическую площадь и планировку;\\n\"\n        \"- состояние подъезда, лифта, фасада, коммуникаций;\\n\"\n        \"- шум, парковку, двор, безопасность вечером;\\n\"\n        \"- реальные цены похожих квартир в этом же доме/ЖК.\"\n    )\n\n    return \"\\n\\n\".join(lines)\n\n\ndef _answer_risks(s: dict, district_avg: float | None, diff_pct: float | None, infra: dict) -> str:\n    lines = [\"## ⚠️ Риски и что проверить\"]\n\n    risks = []\n\n    if diff_pct is not None and diff_pct > 15:\n        risks.append(\"цена выше средней по району — нужно понять, чем оправдана переплата\")\n    if s[\"year\"] and s[\"year\"] < 1985:\n        risks.append(\"старый год постройки — проверь коммуникации, сейсмостойкость, крышу/подвал/лифт\")\n    if infra[\"total\"] <= 3:\n        risks.append(\"по данным карты рядом мало инфраструктуры — проверь местность вручную\")\n    if s[\"floor\"] != \"—\" and any(x in str(s[\"floor\"]).lower() for x in [\"1\", \"перв\"]):\n        risks.append(\"первый этаж может быть дешевле из-за шума, безопасности и приватности\")\n    if s[\"renovation\"] == \"—\":\n        risks.append(\"нет данных о ремонте — цена может быть завышена без качественного ремонта\")\n\n    ctx = _district_context(s[\"district\"])\n    risks.extend(ctx.get(\"risks\", [])[:3])\n\n    if not risks:\n        risks.append(\"критичных рисков из доступных данных не видно, но нужна обычная проверка документов и состояния дома\")\n\n    for r in risks[:8]:\n        lines.append(f\"- {r}\")\n\n    lines.append(\n        \"\\n## Какие вопросы задать продавцу\\n\"\n        \"- Почему продают?\\n\"\n        \"- Есть ли обременения, залог, долги по коммуналке?\\n\"\n        \"- Что входит в цену: мебель, техника, паркинг?\\n\"\n        \"- Когда был ремонт и что менялось в коммуникациях?\\n\"\n        \"- Возможен ли торг и насколько срочная продажа?\"\n    )\n    return \"\\n\".join(lines)\n\n\ndef _answer_investment(s: dict, district_avg: float | None, comparison_text: str, diff_pct: float | None, infra: dict) -> str:\n    lines = [\"## 📈 Инвестиционный взгляд\"]\n\n    if diff_pct is not None:\n        if diff_pct < -10:\n            lines.append(\"Объект может быть интересен как **покупка ниже среднего уровня района**, но нужно проверить причины дисконта.\")\n        elif diff_pct > 15:\n            lines.append(\"Для инвестиции объект выглядит рискованнее: цена уже выше средней, потенциал роста может быть ограничен.\")\n        else:\n            lines.append(\"Цена близка к рынку: инвестиционная привлекательность будет зависеть от аренды, состояния дома и ликвидности.\")\n\n    if infra[\"total\"] >= 15:\n        lines.append(\"- Плюс для аренды: рядом много инфраструктуры.\")\n    else:\n        lines.append(\"- Для аренды нужно проверить транспорт и инфраструктуру вручную.\")\n\n    if s[\"district\"] in [\"Алмалинский\", \"Бостандыкский\", \"Медеуский\"]:\n        lines.append(\"- Район обычно ликвиднее из-за центральности/престижа/деловой активности.\")\n    elif s[\"district\"] in [\"Алатауский\", \"Наурызбайский\"]:\n        lines.append(\"- Район может иметь потенциал роста, но инфраструктурные риски выше.\")\n\n    lines.append(\n        \"\\n**Для инвестиционного решения нужны ещё:** ожидаемая аренда, расходы на ремонт, ликвидность дома, \"\n        \"цены аналогов в этом же ЖК/доме и срок владения.\"\n    )\n    return \"\\n\".join(lines)\n\n\ndef _answer_negotiation(s: dict, district_avg: float | None, comparison_text: str, diff_pct: float | None, infra: dict) -> str:\n    lines = [\"## 🤝 Торг и переговоры\"]\n\n    if diff_pct is not None and diff_pct > 10:\n        lines.append(f\"Есть аргумент для торга: объект **дороже средней цены района**. {comparison_text}\")\n        lines.append(\"Можно просить скидку, если нет сильных преимуществ: новый дом, качественный ремонт, паркинг, вид, хорошая улица.\")\n    elif diff_pct is not None and diff_pct < -10:\n        lines.append(\"Цена уже ниже средней. Сильный торг может быть сложнее, но нужно проверить причины низкой цены.\")\n    else:\n        lines.append(\"Цена близка к рынку. Торг зависит от состояния квартиры, срочности продажи и конкуренции аналогов.\")\n\n    lines.append(\n        \"\\n**Аргументы для торга:**\\n\"\n        \"- старый год постройки или износ подъезда;\\n\"\n        \"- слабый ремонт или отсутствие мебели/техники;\\n\"\n        \"- шумная улица, проблемы с парковкой;\\n\"\n        \"- мало инфраструктуры рядом;\\n\"\n        \"- цена выше средней по району/микрорайону;\\n\"\n        \"- есть похожие объявления дешевле.\"\n    )\n    return \"\\n\".join(lines)\n\n\ndef _answer_location(s: dict, infra: dict) -> str:\n    lines = [\n        \"## 🗺️ Локация объекта\",\n        f\"- **Район:** {s['district']}\",\n        f\"- **Микрорайон:** {s['micro']}\",\n        f\"- **Адрес:** {s['address']}\",\n    ]\n\n    lines.append(_render_location_factors(s))\n    lines.append(_render_infra(infra, limit=8))\n    return \"\\n\\n\".join(lines)\n\n\ndef _answer_general(s: dict, district_avg: float | None, comparison_text: str, diff_pct: float | None, infra: dict) -> str:\n    return \"\\n\\n\".join([\n        _render_header(s, district_avg, comparison_text, diff_pct, infra),\n        _render_location_factors(s),\n        _render_building_factors(s),\n        _render_infra(infra, limit=6),\n        \"## Что можно спросить дальше\\n\"\n        \"- Почему такая цена?\\n\"\n        \"- Какие риски у квартиры?\\n\"\n        \"- Стоит ли покупать для жизни?\\n\"\n        \"- Можно ли торговаться?\\n\"\n        \"- Интересно ли это для инвестиции?\"\n    ])\n\n\n# ============================================================\n# Public API\n# ============================================================\n\ndef answer_question(\n    selected_property: dict,\n    question: str,\n    district_stats: dict,\n    microdistrict_stats: dict | None,\n    nearby_places: dict,\n) -> str:\n    \"\"\"\n    Главная функция ассистента.\n    Возвращает markdown-текст для QTextEdit.\n    \"\"\"\n\n    question = (question or \"\").strip()\n\n    if not _is_relevant_question(question):\n        return _topic_refusal()\n\n    # Optional Claude API\n    api_key = os.getenv(\"ANTHROPIC_API_KEY\")\n    if api_key and requests is not None:\n        try:\n            return _answer_with_anthropic(\n                api_key,\n                selected_property,\n                question,\n                district_stats or {},\n                microdistrict_stats or {},\n                nearby_places or {},\n            )\n        except Exception as e:\n            # Не ломаем приложение, просто идём в локальную логику\n            pass\n\n    return _answer_rule_based(\n        selected_property or {},\n        question,\n        district_stats or {},\n        microdistrict_stats or {},\n        nearby_places or {},\n    )\n\n\ndef _answer_with_anthropic(\n    api_key: str,\n    selected_property: dict,\n    question: str,\n    district_stats: dict,\n    microdistrict_stats: dict,\n    nearby_places: dict,\n) -> str:\n    s = _property_summary(selected_property)\n    infra = _infra_summary(nearby_places)\n    d_avg = _district_avg(district_stats, s[\"district\"])\n    comparison_text, diff_pct = _comparison(s[\"ppm2\"], d_avg, \"району\")\n\n    context = {\n        \"selected_property\": s,\n        \"district_average_price_m2\": d_avg,\n        \"comparison\": comparison_text,\n        \"nearby_total\": infra[\"total\"],\n        \"nearby_top\": infra[\"rows\"][:20],\n        \"district_context\": _district_context(s[\"district\"]),\n        \"microdistrict_hint\": _micro_hint(s[\"micro\"]),\n    }\n\n    system_prompt = (\n        \"Ты — профессиональный ассистент по рынку недвижимости Алматы. \"\n        \"Отвечай только на русском языке и только по теме выбранной недвижимости. \"\n        \"Если вопрос не относится к недвижимости, откажись кратко. \"\n        \"Не выдумывай факты. Если данных нет, честно скажи. \"\n        \"Давай структурированный ответ: вывод, цена, локация, инфраструктура, риски, рекомендация. \"\n        \"Не обещай гарантированную доходность и не давай юридических гарантий.\"\n    )\n\n    payload = {\n        \"model\": \"claude-sonnet-4-20250514\",\n        \"max_tokens\": 1200,\n        \"system\": system_prompt,\n        \"messages\": [\n            {\n                \"role\": \"user\",\n                \"content\": (\n                    \"Данные по объекту и окружению:\\n\"\n                    + json.dumps(context, ensure_ascii=False, indent=2)\n                    + \"\\n\\nВопрос пользователя: \"\n                    + question\n                ),\n            }\n        ],\n    }\n\n    headers = {\n        \"x-api-key\": api_key,\n        \"anthropic-version\": \"2023-06-01\",\n        \"content-type\": \"application/json\",\n    }\n\n    resp = requests.post(\n        \"https://api.anthropic.com/v1/messages\",\n        headers=headers,\n        json=payload,\n        timeout=35,\n    )\n    resp.raise_for_status()\n    data = resp.json()\n    return data[\"content\"][0][\"text\"]\n\n\ndef _answer_rule_based(\n    selected_property: dict,\n    question: str,\n    district_stats: dict,\n    microdistrict_stats: dict | None,\n    nearby_places: dict,\n) -> str:\n    q = question.lower()\n    s = _property_summary(selected_property)\n    infra = _infra_summary(nearby_places)\n    d_avg = _district_avg(district_stats, s[\"district\"])\n    comparison_text, diff_pct = _comparison(s[\"ppm2\"], d_avg, \"району\")\n\n    if any(x in q for x in [\"цена\", \"почему\", \"дорого\", \"дешево\", \"дёшево\", \"стоимость\", \"стоит\"]):\n        return _answer_price(s, d_avg, comparison_text, diff_pct, infra)\n\n    if any(x in q for x in [\"рядом\", \"инфраструкт\", \"школ\", \"сад\", \"магазин\", \"трц\", \"парк\", \"больниц\", \"клиник\", \"останов\", \"метро\"]):\n        return _answer_nearby(s, infra)\n\n    if any(x in q for x in [\"сравн\", \"средн\", \"переплат\", \"дешевле\", \"дороже\", \"район\"]):\n        return _answer_compare(s, d_avg, comparison_text, diff_pct, infra)\n\n    if any(x in q for x in [\"жить\", \"для жизни\", \"подходит\", \"хорош\", \"рекоменд\", \"семь\", \"семья\"]):\n        return _answer_suitability(s, d_avg, comparison_text, diff_pct, infra)\n\n    if any(x in q for x in [\"риск\", \"минус\", \"плох\", \"опас\", \"провер\", \"документ\"]):\n        return _answer_risks(s, d_avg, diff_pct, infra)\n\n    if any(x in q for x in [\"инвест\", \"аренд\", \"сдать\", \"ликвид\", \"рост\"]):\n        return _answer_investment(s, d_avg, comparison_text, diff_pct, infra)\n\n    if any(x in q for x in [\"торг\", \"скид\", \"переговор\", \"снизить\"]):\n        return _answer_negotiation(s, d_avg, comparison_text, diff_pct, infra)\n\n    if any(x in q for x in [\"адрес\", \"локац\", \"микрорайон\", \"координат\", \"где находится\"]):\n        return _answer_location(s, infra)\n\n    if any(x in q for x in [\"истор\", \"золотой квадрат\", \"арбат\", \"цум\", \"театр\", \"музей\"]):\n        return \"\\n\\n\".join([\n            \"## 🏛️ Исторические и городские факторы\",\n            _render_location_factors(s),\n            \"Исторические и культурные объекты обычно повышают ценность локации не напрямую сами по себе, \"\n            \"а через центральность, престиж, пешеходную активность, аренду, транспорт и насыщенную инфраструктуру.\",\n            _answer_price(s, d_avg, comparison_text, diff_pct, infra),\n        ])\n\n    return _answer_general(s, d_avg, comparison_text, diff_pct, infra)\n"
